// header + payload into b (room for ZC_HDR_LEN + ZC_LEN_MOTION_CMD), returns the datagram length
static inline int zc_msg_motion_cmd(uint8_t *b, uint8_t flags, uint32_t seq, uint64_t ts, const zc_motion_cmd_t *s) {
  const zc_hdr_t h = zc_hdr(ZC_TYPE_MOTION_CMD, ZC_ID_MOTION_CMD, ZC_CLASS_MOTION_CMD, flags, seq, ts);
  return zc_put_hdr(b, &h) + zc_put_motion_cmd(b + ZC_HDR_LEN, s);
}
// the catalogue's safe values (fields marked hold, or without one, keep their last value)
static inline void zc_safe_motion_cmd(zc_motion_cmd_t *s) {
  s->ctl = (uint8_t)(s->ctl & ~ZC_MOTION_CMD_CTL_MOTORS_ON);
  s->ctl = (uint8_t)(s->ctl | ZC_MOTION_CMD_CTL_BRAKE);
}

static inline int zc_put_motion_telemetry(uint8_t *p, const zc_motion_telemetry_t *s) {
  zc_w16(p + 0, (uint16_t)s->status);
  zc_w16(p + 2, (uint16_t)s->cmd_age_ms);
  zc_w32(p + 4, (uint32_t)s->enc_a);
  zc_w32(p + 8, (uint32_t)s->enc_b);
  zc_w16(p + 12, (uint16_t)s->w_a100);
  zc_w16(p + 14, (uint16_t)s->w_b100);
  zc_w16(p + 16, (uint16_t)s->i_a_ma);
  zc_w16(p + 18, (uint16_t)s->i_b_ma);
  zc_w16(p + 20, (uint16_t)s->duty_a);
  zc_w16(p + 22, (uint16_t)s->duty_b);
  p[24] = (uint8_t)s->imu_kind;
  p[25] = (uint8_t)s->imu_flags;
  zc_w16(p + 26, (uint16_t)s->quat[0]);
  zc_w16(p + 28, (uint16_t)s->quat[1]);
  zc_w16(p + 30, (uint16_t)s->quat[2]);
  zc_w16(p + 32, (uint16_t)s->quat[3]);
  zc_w16(p + 34, (uint16_t)s->accel100[0]);
  zc_w16(p + 36, (uint16_t)s->accel100[1]);
  zc_w16(p + 38, (uint16_t)s->accel100[2]);
  zc_w16(p + 40, (uint16_t)s->gyro1000[0]);
  zc_w16(p + 42, (uint16_t)s->gyro1000[1]);
  zc_w16(p + 44, (uint16_t)s->gyro1000[2]);
  zc_w16(p + 46, (uint16_t)s->servo_us[0]);
  zc_w16(p + 48, (uint16_t)s->servo_us[1]);
  zc_w16(p + 50, (uint16_t)s->servo_us[2]);
  zc_w16(p + 52, (uint16_t)s->servo_us[3]);
  zc_w16(p + 54, (uint16_t)s->veh_steer100);
  zc_w16(p + 56, (uint16_t)s->veh_speed_mm);
  zc_w16(p + 58, (uint16_t)s->veh_curv1000);
  zc_w16(p + 60, (uint16_t)s->vbat_mv);
  p[62] = (uint8_t)s->profile;
  p[63] = (uint8_t)s->veh_flags;
  return ZC_LEN_MOTION_TELEMETRY;
}
static inline int zc_get_motion_telemetry(const uint8_t *p, size_t n, zc_motion_telemetry_t *s) {
  if (n < ZC_LEN_MOTION_TELEMETRY) return ZC_E_PAYLOAD;
  s->status = (uint16_t)zc_r16(p + 0);
  s->cmd_age_ms = (uint16_t)zc_r16(p + 2);
  s->enc_a = (int32_t)zc_r32(p + 4);
  s->enc_b = (int32_t)zc_r32(p + 8);
  s->w_a100 = (int16_t)zc_r16(p + 12);
  s->w_b100 = (int16_t)zc_r16(p + 14);
  s->i_a_ma = (uint16_t)zc_r16(p + 16);
  s->i_b_ma = (uint16_t)zc_r16(p + 18);
  s->duty_a = (int16_t)zc_r16(p + 20);
  s->duty_b = (int16_t)zc_r16(p + 22);
  s->imu_kind = (uint8_t)p[24];
  s->imu_flags = (uint8_t)p[25];
  s->quat[0] = (int16_t)zc_r16(p + 26);
  s->quat[1] = (int16_t)zc_r16(p + 28);
  s->quat[2] = (int16_t)zc_r16(p + 30);
  s->quat[3] = (int16_t)zc_r16(p + 32);
  s->accel100[0] = (int16_t)zc_r16(p + 34);
  s->accel100[1] = (int16_t)zc_r16(p + 36);
  s->accel100[2] = (int16_t)zc_r16(p + 38);
  s->gyro1000[0] = (int16_t)zc_r16(p + 40);
  s->gyro1000[1] = (int16_t)zc_r16(p + 42);
  s->gyro1000[2] = (int16_t)zc_r16(p + 44);
  s->servo_us[0] = (uint16_t)zc_r16(p + 46);
  s->servo_us[1] = (uint16_t)zc_r16(p + 48);
  s->servo_us[2] = (uint16_t)zc_r16(p + 50);
  s->servo_us[3] = (uint16_t)zc_r16(p + 52);
  s->veh_steer100 = (int16_t)zc_r16(p + 54);
  s->veh_speed_mm = (int16_t)zc_r16(p + 56);
  s->veh_curv1000 = (int16_t)zc_r16(p + 58);
  s->vbat_mv = (uint16_t)zc_r16(p + 60);
  s->profile = (uint8_t)p[62];
  s->veh_flags = (uint8_t)p[63];
  return ZC_OK;
}
// header + payload into b (room for ZC_HDR_LEN + ZC_LEN_MOTION_TELEMETRY), returns the datagram length
static inline int zc_msg_motion_telemetry(uint8_t *b, uint8_t flags, uint32_t seq, uint64_t ts, const zc_motion_telemetry_t *s) {
  const zc_hdr_t h = zc_hdr(ZC_TYPE_MOTION_TELEMETRY, ZC_ID_MOTION_TELEMETRY, ZC_CLASS_MOTION_TELEMETRY, flags, seq, ts);
  return zc_put_hdr(b, &h) + zc_put_motion_telemetry(b + ZC_HDR_LEN, s);
}
// the catalogue's safe values (fields marked hold, or without one, keep their last value)
static inline void zc_safe_motion_telemetry(zc_motion_telemetry_t *s) {
  (void)s;
}

// ---- the table: what a receiver needs to know about an id without its codec
enum { ZC_DIR_ZONE_TO_GW = 0, ZC_DIR_GW_TO_ZONE = 1, ZC_DIR_NODE_TO_GW = 2, ZC_DIR_GW_TO_NODE = 3 };
typedef struct {
  uint16_t id;
  uint8_t type, cls, ack, dir;
  uint16_t len, period_ms, max_age_ms, port;
  const char *name;
} zc_item_t;
static const zc_item_t zc_catalog[] = {
    {0x0001, 6, 2, 0, 2, 12, 1000, 3000, 5009, "core.heartbeat"},
    {0x0010, 5, 2, 0, 2, 12, 1000, 3000, 5009, "zone.diag"},
    {0x0110, 2, 0, 1, 1, 1, 0, 5, 5006, "body.lights.indicator"},
    {0x0120, 3, 0, 1, 0, 1, 0, 5, 5009, "powertrain.gear.target"},
    {0x8001, 1, 1, 0, 1, 9, 50, 500, 5008, "zone.body.state_in"},
    {0x8002, 1, 1, 0, 0, 8, 50, 150, 5009, "zone.body.sensors_out"},
    {0x8003, 1, 1, 0, 3, 26, 20, 500, 5008, "motion.cmd"},
    {0x8004, 1, 1, 0, 2, 64, 20, 100, 5009, "motion.telemetry"},
};
#define ZC_CATALOG_COUNT 8
static inline const zc_item_t *zc_catalog_find(uint16_t id) {
  for (int i = 0; i < ZC_CATALOG_COUNT; i++)
    if (zc_catalog[i].id == id) return &zc_catalog[i];
  return NULL;
}

